66	/**
67	 * @author Vitaliy Fedoriv
68	 */
69	
70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    /**
76	     * Syntactic email validation: a non-empty local part, a single '@', and a
77	     * domain with at least one dot-separated label ending in a letter-only TLD.
78	     */
79	    private static final Pattern EMAIL_PATTERN =
80	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
81	
82	    /**
83	     * Disposable / throw-away email domains whose owners are rejected: an email on one of these
84	     * domains is treated as invalid input and rejected with 400. Compared case-insensitively.
85	     */
86	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
87	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
88	
89	    /**
90	     * Fixed public-holiday list. A registration date that lands on one of these is not a business
91	     * day and is rolled forward to the next non-holiday weekday.
92	     */
93	    private static final java.util.Set<LocalDate> PUBLIC_HOLIDAYS =
94	        java.util.Set.of(
95	            LocalDate.of(2026, 1, 1),
96	            LocalDate.of(2026, 1, 26),
97	            LocalDate.of(2026, 4, 25),
98	            LocalDate.of(2026, 12, 25),
99	            LocalDate.of(2026, 12, 28));
100	
101	    /** Dedicated audit logger for owner lifecycle side-effects. */
102	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
103	
104	    /** Dedicated logger for outbound member notifications (e.g. the welcome notification). */
105	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
106	
107	    /**
108	     * Monotonically increasing sequence number stamped onto the structured {@code OWNER_CREATED}
109	     * audit event, incremented once per successful create so events are strictly ordered.
110	     */
111	    private static final AtomicLong CREATE_SEQUENCE = new AtomicLong();
112	
113	    /** Request header carrying the client-supplied idempotency key for owner creation. */
114	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
115	
116	    /**
117	     * Remembers which owner was created for each already-seen idempotency key, so a repeated create
118	     * carrying a key seen before returns the originally created owner instead of creating a duplicate.
119	     */
120	    private final Map<String, Integer> idempotentCreations = new ConcurrentHashMap<>();
121	
122	    private final ClinicService clinicService;
123	
124	    private final OwnerMapper ownerMapper;
125	
126	    private final PetMapper petMapper;
127	
128	    private final VisitMapper visitMapper;
129	
130	    public OwnerRestControllerV1(ClinicService clinicService,
131	                                 OwnerMapper ownerMapper,
132	                                 PetMapper petMapper,
133	                                 VisitMapper visitMapper) {
134	        this.clinicService = clinicService;
135	        this.ownerMapper = ownerMapper;
136	        this.petMapper = petMapper;
137	        this.visitMapper = visitMapper;
138	    }
139	
140	    /**
141	     * Normalise a raw telephone number to E.164 form.
142	     *
143	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
144	     * code are kept when present; otherwise country code '+61' is assumed and a
145	     * single leading '0' is dropped from the national digits. The result must have
146	     * between 8 and 15 digits after the '+'.
147	     *
148	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
149	     * national-number length is additionally validated against that country code:
150	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
151	     * length is wrong for its country is rejected.
152	     *
153	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
154	     */
155	    static String toE164(String raw) {
156	        if (raw == null) {
157	            return null;
158	        }
159	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
160	        String digits;
161	        boolean explicitCountryCode;
162	        if (cleaned.startsWith("+")) {
163	            digits = cleaned.substring(1);
164	            explicitCountryCode = true;
165	        } else {
166	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
167	            digits = "61" + national;
168	            explicitCountryCode = false;
169	        }
170	        if (!digits.matches("[0-9]{8,15}")) {
171	            return null;
172	        }
173	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
174	            return null;
175	        }
176	        return "+" + digits;
177	    }
178	
179	    /**
180	     * Validate the national-number length of an E.164 number (its digits without the
181	     * leading '+') against the requirement for its country code: country code '+61'
182	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
183	     * without a configured length requirement are accepted unchanged.
184	     */
185	    private static boolean hasValidNationalLength(String digits) {
186	        if (digits.startsWith("61")) {
187	            return digits.length() - "61".length() == 9;
188	        }
189	        if (digits.startsWith("1")) {
190	            return digits.length() - "1".length() == 10;
191	        }
192	        return true;
193	    }
194	
195	    /**
196	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
197	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
198	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
199	     * input normalises to the empty string.
200	     */
201	    private static String normaliseIdentity(String value) {
202	        if (value == null) {
203	            return "";
204	        }
205	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
206	    }
207	
208	    /**
209	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
210	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
211	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
212	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
213	     * that is both stored and used for every address comparison.
214	     */
215	    static String normaliseAddress(String value) {
216	        if (value == null) {
217	            return "";
218	        }
219	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
220	        if (collapsed.isEmpty()) {
221	            return "";
222	        }
223	        String[] tokens = collapsed.split(" ");
224	        StringBuilder result = new StringBuilder();
225	        for (int i = 0; i < tokens.length; i++) {
226	            if (i > 0) {
227	                result.append(' ');
228	            }
229	            result.append(expandAddressAbbreviation(tokens[i]));
230	        }
231	        return result.toString();
232	    }
233	
234	    /**
235	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
236	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
237	     * returned unchanged.
238	     */
239	    private static String expandAddressAbbreviation(String token) {
240	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
241	        return switch (core) {
242	            case "ST" -> "STREET";
243	            case "RD" -> "ROAD";
244	            case "AVE" -> "AVENUE";
245	            default -> token;
246	        };
247	    }
248	
249	    /**
250	     * Derive the stable, shared household identifier for owners in the same household: the first 12
251	     * lower-case hex characters of the SHA-256 digest over
252	     * {@code '<VERSION_TAG>|<normalizedLastName>|<postcode>'}, so every owner with the same last name
253	     * and postcode resolves to the same value regardless of the order in which they were created. The
254	     * fixed {@code V2} version tag is mixed in so the value differs from its version-1 form.
255	     */
256	    private static String householdId(String lastNameKey, String postcode) {
257	        return hashHex(OwnerIdentity.VERSION_TAG + "|" + lastNameKey + "|" + (postcode == null ? "" : postcode),
258	            12, false);
259	    }
260	
261	    /**
262	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
263	     * name and postcode). An owner without a postcode has no household peers and counts as a household
264	     * of one.
265	     */
266	    private int householdSize(Owner owner) {
267	        if (owner.getPostcode() == null) {
268	            return 1;
269	        }
270	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
271	        return (int) this.clinicService.findAllOwners().stream()
272	            .filter(existing -> existing.getPostcode() != null
273	                && householdId.equals(
274	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
275	            .count();
276	    }
277	
278	    /**
279	     * The existing, non-deleted owners that belong to {@code owner}'s household (sharing its
280	     * normalized last name and postcode), excluding {@code owner} itself. An owner without a
281	     * postcode has no household peers, so this is empty.
282	     */
283	    private List<Owner> otherHouseholdMembers(Owner owner) {
284	        if (owner.getPostcode() == null) {
285	            return List.of();
286	        }
287	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
288	        return this.clinicService.findAllOwners().stream()
289	            .filter(existing -> !existing.isDeleted())
290	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
291	            .filter(existing -> existing.getPostcode() != null
292	                && householdId.equals(
293	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
294	            .toList();
295	    }
296	
297	    /**
298	     * The owner's membership level after applying the household ceiling: the natural level derived
299	     * from the owner's membership points, capped at one above the current maximum membership level
300	     * among the owner's existing household members. With no existing household member no cap applies.
301	     * Assumes the owner's household size has already been populated.
302	     */
303	    private Integer cappedMembershipLevel(Owner owner) {
304	        Integer natural = ownerMapper.formatMembershipLevel(owner);
305	        if (natural == null) {
306	            return null;
307	        }
308	        List<Owner> members = otherHouseholdMembers(owner);
309	        if (members.isEmpty()) {
310	            return natural;
311	        }
312	        int maxMemberLevel = 0;
313	        for (Owner member : members) {
314	            member.setHouseholdSize(householdSize(member));
315	            Integer memberLevel = ownerMapper.formatMembershipLevel(member);
316	            if (memberLevel != null) {
317	                maxMemberLevel = Math.max(maxMemberLevel, memberLevel);
318	            }
319	        }
320	        return Math.min(natural, maxMemberLevel + 1);
321	    }
322	
323	    /**
324	     * Build the unified member id for a new owner as {@code '<REGION><FY><HASH8><CHK>'}, where REGION is
325	     * the version-2 region code — the fixed {@code V2} version tag prepended to the region derived from
326	     * the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"}) — FY is the
327	     * two-digit fiscal year (starting 1 July) of the business-day-adjusted {@code registrationDate},
328	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
329	     * {@code normalizedTelephone + lastName}, and CHK is a single Luhn check digit computed over the
330	     * digits of {@code '<REGION><FY><HASH8>'}. The version tag ensures the id differs from its
331	     * version-1 form; the id otherwise depends only on the owner's own region, fiscal year and
332	     * identity, not on how many owners already exist.
333	     */
334	    private String nextMemberId(String region, LocalDate registrationDate,
335	                                String normalizedTelephone, String lastName) {
336	        String fiscalYear = String.format("%02d", fiscalYearStart(registrationDate) % 100);
337	        String hash8 = hash8(normalizedTelephone + (lastName == null ? "" : lastName));
338	        String base = OwnerIdentity.regionCode(region) + fiscalYear + hash8;
339	        return base + luhnCheckDigit(base);
340	    }
341	
342	    /**
343	     * De-duplicate a computed member id against the ids already assigned to existing owners: when
344	     * {@code memberId} is unused it is returned unchanged, otherwise {@code '-<n>'} is appended with
345	     * the smallest {@code n} of 2 or more that makes the result unique among existing owners.
346	     */
347	    private String deduplicateMemberId(String memberId) {
348	        Set<String> existing = this.clinicService.findAllOwners().stream()
349	            .map(Owner::getMemberId)
350	            .filter(Objects::nonNull)
351	            .collect(Collectors.toSet());
352	        if (!existing.contains(memberId)) {
353	            return memberId;
354	        }
355	        int n = 2;
356	        while (existing.contains(memberId + "-" + n)) {
357	            n++;
358	        }
359	        return memberId + "-" + n;
360	    }
361	
362	    /**
363	     * The starting calendar year of the fiscal year (which starts on 1 July) that contains the given
364	     * date: the date's own year when it falls on or after 1 July, otherwise the previous year.
365	     */
366	    private static int fiscalYearStart(LocalDate date) {
367	        return date.getMonthValue() >= 7 ? date.getYear() : date.getYear() - 1;
368	    }
369	
370	    /**
371	     * A single Luhn check digit (0-9) computed over the digits contained in {@code input}
372	     * (non-digit characters are ignored).
373	     */
374	    private static int luhnCheckDigit(String input) {
375	        int sum = 0;
376	        boolean dbl = true;
377	        for (int i = input.length() - 1; i >= 0; i--) {
378	            char c = input.charAt(i);
379	            if (c < '0' || c > '9') {
380	                continue;
381	            }
382	            int d = c - '0';
383	            if (dbl) {
384	                d *= 2;
385	                if (d > 9) {
386	                    d -= 9;
387	                }
388	            }
389	            sum += d;
390	            dbl = !dbl;
391	        }
392	        return (10 - (sum % 10)) % 10;
393	    }
394	
395	    /**
396	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
397	     */
398	    private static String hash8(String input) {
399	        return hashHex(input, 8, true);
400	    }
401	
402	    /**
403	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
404	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
405	     */
406	    private static String hashHex(String input, int length, boolean upperCase) {
407	        try {
408	            byte[] digest = MessageDigest.getInstance("SHA-256")
409	                .digest(input.getBytes(StandardCharsets.UTF_8));
410	            StringBuilder sb = new StringBuilder(digest.length * 2);
411	            for (byte b : digest) {
412	                sb.append(String.format("%02x", b));
413	            }
414	            String hex = sb.substring(0, length);
415	            return upperCase ? hex.toUpperCase() : hex;
416	        }
417	        catch (java.security.NoSuchAlgorithmException e) {
418	            throw new IllegalStateException(e);
419	        }
420	    }
421	
422	    /**
423	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
424	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
425	     * fixed city-to-region table, else {@code "UNKNOWN"}.
426	     */
427	    private static String region(String postcode, String city) {
428	        String fromPostcode = regionForPostcode(postcode);
429	        return fromPostcode != null ? fromPostcode : regionForCity(city);
430	    }
431	
432	    /**
433	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
434	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
435	     */
436	    private static String regionForPostcode(String postcode) {
437	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
438	            return null;
439	        }
440	        int value = Integer.parseInt(postcode);
441	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
442	            int[] range = entry.getValue();
443	            if (value >= range[0] && value <= range[1]) {
444	                return entry.getKey();
445	            }
446	        }
447	        return null;
448	    }
449	
450	    /**
451	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
452	     * Sunday, or on a listed public holiday, it is advanced day by day to the next non-holiday
453	     * weekday; ordinary weekday dates are returned unchanged.
454	     */
455	    static LocalDate toBusinessDay(LocalDate date) {
456	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
457	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
458	            || PUBLIC_HOLIDAYS.contains(date)) {
459	            date = date.plusDays(1);
460	        }
461	        return date;
462	    }
463	
464	    /**
465	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
466	     * using the same per-day accumulation path as the daily create-limit rule.
467	     */
468	    private long ownersCreatedOn(LocalDate registrationDate) {
469	        LocalDate day = toBusinessDay(registrationDate);
470	        return this.clinicService.findAllOwners().stream()
471	            .map(Owner::getRegistrationDate)
472	            .filter(existing -> existing != null)
473	            .map(OwnerRestControllerV1::toBusinessDay)
474	            .filter(day::equals)
475	            .count();
476	    }
477	
478	    /**
479	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
480	     * postcode against the owner's city region.
481	     */
482	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
483	        "NSW", new int[] {2000, 2099},
484	        "VIC", new int[] {3000, 3099},
485	        "QLD", new int[] {4000, 4099});
486	
487	    /**
488	     * Resolve an owner's region from the city using the fixed city-to-region table
489	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
490	     * when the city is not listed.
491	     */
492	    private static String regionForCity(String city) {
493	        return switch (city == null ? "" : city) {
494	            case "Sydney" -> "NSW";
495	            case "Melbourne" -> "VIC";
496	            case "Brisbane" -> "QLD";
497	            default -> "UNKNOWN";
498	        };
499	    }
500	
501	    /**
502	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
503	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
504	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
505	     */
506	    private static boolean isPostcodeValid(String postcode, String city) {
507	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
508	            return false;
509	        }
510	        int[] range = REGION_POSTCODES.get(regionForCity(city));
511	        if (range == null) {
512	            return true;
513	        }
514	        int value = Integer.parseInt(postcode);
515	        return value >= range[0] && value <= range[1];
516	    }
517	
518	    /**
519	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
520	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
521	     */
522	    private static boolean isDisposableEmailDomain(String email) {
523	        if (email == null) {
524	            return false;
525	        }
526	        int at = email.lastIndexOf('@');
527	        if (at < 0 || at == email.length() - 1) {
528	            return false;
529	        }
530	        String domain = email.substring(at + 1).toLowerCase();
531	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
532	    }
533	
534	    /**
535	     * Whether the owner's city is approaching the per-city capacity limit of 50 owners: true when the
536	     * city already holds between 40 and 49 owners (counted the same way as the hard-limit rule, over
537	     * all owners with a matching, normalized city), otherwise false.
538	     */
539	    private boolean capacityWarning(String city) {
540	        String cityKey = normaliseIdentity(city);
541	        long ownersInCity = this.clinicService.findAllOwners().stream()
542	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
543	            .count();
544	        return ownersInCity >= 40 && ownersInCity <= 49;
545	    }
546	
547	    /**
548	     * The soft, review-triggering per-city capacity threshold (as opposed to the hard 50-owner limit
549	     * that rejects a create): a city holding this many owners or more is considered over soft capacity.
550	     */
551	    private static final int SOFT_CITY_CAPACITY = 40;
552	
553	    /**
554	     * Whether the owner's city is over its soft capacity: true when the city already holds
555	     * {@link #SOFT_CITY_CAPACITY} owners or more (counted the same way as the hard-limit rule, over all
556	     * owners with a matching, normalized city), otherwise false.
557	     */
558	    private boolean overSoftCityCapacity(String city) {
559	        String cityKey = normaliseIdentity(city);
560	        long ownersInCity = this.clinicService.findAllOwners().stream()
561	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
562	            .count();
563	        return ownersInCity >= SOFT_CITY_CAPACITY;
564	    }
565	
566	    /**
567	     * Whether the email's domain (the part after the final '@') is disposable-adjacent: it is one of
568	     * the disposable domains, or a subdomain of one (it ends with {@code '.<disposableDomain>'}). This
569	     * is broader than {@link #isDisposableEmailDomain(String)} (which rejects an exact disposable
570	     * domain at create time): an owner whose stored email sits just off the blocklist is flagged for
571	     * review rather than rejected. A {@code null} email is not disposable-adjacent; the comparison is
572	     * case-insensitive.
573	     */
574	    private static boolean isDisposableAdjacentEmailDomain(String email) {
575	        if (email == null) {
576	            return false;
577	        }
578	        int at = email.lastIndexOf('@');
579	        if (at < 0 || at == email.length() - 1) {
580	            return false;
581	        }
582	        String domain = email.substring(at + 1).toLowerCase();
583	        for (String disposable : DISPOSABLE_EMAIL_DOMAINS) {
584	            if (domain.equals(disposable) || domain.endsWith("." + disposable)) {
585	                return true;
586	            }
587	        }
588	        return false;
589	    }
590	
591	    /**
592	     * The owner's risk flag: true when any of these hold — the owner is a possible duplicate
593	     * (a {@code possibleDuplicateOf} target exists), the email domain is disposable-adjacent, or the
594	     * owner's city is over its soft capacity; otherwise false.
595	     */
596	    private boolean riskFlag(Owner owner) {
597	        return owner.getPossibleDuplicateOf() != null
598	            || isDisposableAdjacentEmailDomain(owner.getEmail())
599	            || overSoftCityCapacity(owner.getCity());
600	    }
