634	
635	    /**
636	     * The value of the {@code Idempotency-Key} header on the current request, or {@code null} when the
637	     * request carries no such header (or there is no active servlet request). A blank value is treated
638	     * as absent.
639	     */
640	    private static String currentIdempotencyKey() {
641	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
642	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
643	            return null;
644	        }
645	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
646	        return (key == null || key.isBlank()) ? null : key;
647	    }
