649	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
650	    @Override
651	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
652	        String idempotencyKey = currentIdempotencyKey();
653	        if (idempotencyKey != null) {
654	            Integer existingId = this.idempotentCreations.get(idempotencyKey);
655	            if (existingId != null) {
656	                Owner existing = this.clinicService.findOwnerById(existingId);
657	                if (existing != null) {
658	                    existing.setHouseholdSize(householdSize(existing));
659	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
660	                    existingDto.setMembershipLevel(cappedMembershipLevel(existing));
661	                    existingDto.setBulkSignupWarning(existing.getRegistrationDate() != null
662	                        && ownersCreatedOn(existing.getRegistrationDate()) > 80);
663	                    existingDto.setCapacityWarning(capacityWarning(existing.getCity()));
664	                    existingDto.setRiskFlag(riskFlag(existing));
665	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
666	                }
667	            }
668	        }
669	        String telephone = toE164(ownerFieldsDto.getTelephone());
670	        if (telephone == null) {
671	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied telephone number is not valid");
672	        }
673	        String email = ownerFieldsDto.getEmail();
674	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
675	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied email address is not valid");
676	        }
677	        if (isDisposableEmailDomain(email)) {
678	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Disposable email addresses are not accepted");
679	        }
680	        // Structured address is preferred when supplied (a non-blank 'addressLine1'); otherwise the
681	        // flat 'address' input is used for backward compatibility. Normalization applies to whichever
682	        // fields are supplied, and the composed 'address' is the normalized addressLine1 with the
683	        // normalized addressLine2 appended after a single space when present.
684	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
685	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
686	        boolean structuredAddress = !addressLine1.isEmpty();
687	        String address;
688	        if (structuredAddress) {
689	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
690	        } else {
691	            address = normaliseAddress(ownerFieldsDto.getAddress());
692	        }
693	        if (address.isEmpty()) {
694	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An address is required");
695	        }
696	        String postcode = ownerFieldsDto.getPostcode();
697	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
698	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied postcode is not valid for the city");
699	        }
700	        if (ownerFieldsDto.getRegistrationDate() != null
701	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
702	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The registration date cannot be in the future");
703	        }
704	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
705	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
706	        LocalDate registrationDate = toBusinessDay(effectiveDate);
707	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
708	            .map(Owner::getRegistrationDate)
709	            .filter(existing -> existing != null)
710	            .map(OwnerRestControllerV1::toBusinessDay)
711	            .filter(registrationDate::equals)
712	            .count();
713	        if (ownersCreatedThatDay >= 100) {
714	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
715	                "The daily owner-registration limit has been reached");
716	        }
717	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
718	        long ownersInCity = this.clinicService.findAllOwners().stream()
719	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
720	            .count();
721	        if (ownersInCity >= 50) {
722	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The city has reached its owner capacity");
723	        }
724	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
725	        // The household is deterministically keyed on (normalized last name, postcode): every owner
726	        // with a postcode belongs to the household identified by this computed id, and owners sharing
727	        // a last name and postcode share it automatically. A new owner may join an existing household;
728	        // the household ceiling below (rather than a hard rejection) governs its membership level.
729	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
730	        // Duplicate detection is the single identity key (normalized telephone, lower-cased email and
731	        // Soundex of the last name). A candidate whose key collides with an existing, non-deleted
732	        // owner is a hard duplicate (409); the household id no longer participates in this decision.
733	        String identityKey = OwnerIdentity.identityKey(telephone, email, ownerFieldsDto.getLastName());
734	        boolean identityInUse = this.clinicService.findAllOwners().stream()
735	            .filter(existing -> !existing.isDeleted())
736	            .anyMatch(existing -> OwnerIdentity.identityKey(toE164(existing.getTelephone()),
737	                existing.getEmail(), existing.getLastName()).equals(identityKey));
738	        if (identityInUse) {
739	            throw new ResponseStatusException(HttpStatus.CONFLICT, "An owner with the same identity already exists");
740	        }
741	        // Soft match: an existing, non-deleted owner sharing this owner's postcode and last-name
742	        // Soundex but with a different identity key (e.g. a different telephone) is not a hard
743	        // duplicate, but the new owner is flagged as a possible duplicate of it.
744	        String lastNameSoundex = OwnerIdentity.soundex(ownerFieldsDto.getLastName());
745	        Integer possibleDuplicateOf = (postcode == null) ? null
746	            : this.clinicService.findAllOwners().stream()
747	                .filter(existing -> !existing.isDeleted())
748	                .filter(existing -> postcode.equals(existing.getPostcode()))
749	                .filter(existing -> lastNameSoundex.equals(OwnerIdentity.soundex(existing.getLastName())))
750	                .filter(existing -> !OwnerIdentity.identityKey(toE164(existing.getTelephone()),
751	                    existing.getEmail(), existing.getLastName()).equals(identityKey))
752	                .map(Owner::getId)
753	                .findFirst()
754	                .orElse(null);
755	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
756	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
757	            .filter(existing ->
758	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
759	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
760	            .count();
761	        HttpHeaders headers = new HttpHeaders();
762	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
763	        owner.setNamesakeCount(namesakeCount);
764	        owner.setAddress(address);
765	        if (structuredAddress) {
766	            owner.setAddressLine1(addressLine1);
767	            owner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
768	        } else {
769	            owner.setAddressLine1(null);
770	            owner.setAddressLine2(null);
771	        }
772	        owner.setTelephone(telephone);
773	        owner.setEmail(email == null ? null : email.toLowerCase());
774	        owner.setRegistrationDate(registrationDate);
775	        owner.setMemberId(deduplicateMemberId(nextMemberId(
776	            region(postcode, owner.getCity()), registrationDate, telephone, owner.getLastName())));
777	        owner.setHouseholdId(householdId);
778	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
779	        this.clinicService.saveOwner(owner);
780	        if (idempotencyKey != null) {
781	            this.idempotentCreations.put(idempotencyKey, owner.getId());
782	        }
783	        owner.setHouseholdSize(householdSize(owner));
784	        Integer membershipLevel = cappedMembershipLevel(owner);
785	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
786	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
787	        // Immutable structured event carrying the owner's current primary identifier (the
788	        // unified memberId), with a monotonic sequence.
789	        AUDIT.info(new OwnerCreatedEvent(CREATE_SEQUENCE.incrementAndGet(), owner.getId(),
790	            owner.getMemberId(), membershipLevel).toJson());
791	        // Enqueue a welcome notification for the newly created owner, carrying its id and memberId.
792	        NOTIFY.info("welcome notification: ownerId={} memberId={}",
793	            owner.getId(), owner.getMemberId());
794	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
795	        ownerDto.setMembershipLevel(membershipLevel);
796	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
797	        ownerDto.setCapacityWarning(capacityWarning(owner.getCity()));
798	        ownerDto.setRiskFlag(riskFlag(owner));
799	        headers.setLocation(UriComponentsBuilder.newInstance()
800	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
801	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
802	    }
803	
804	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
805	    @Override
806	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
807	        String telephone = toE164(ownerFieldsDto.getTelephone());
808	        if (telephone == null) {
809	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied telephone number is not valid");
810	        }
811	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
812	        if (currentOwner == null) {
813	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
814	        }
815	        String email = ownerFieldsDto.getEmail();
816	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
817	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The supplied email address is not valid");
818	        }
819	        String addressLine1 = normaliseAddress(ownerFieldsDto.getAddressLine1());
820	        String addressLine2 = normaliseAddress(ownerFieldsDto.getAddressLine2());
821	        if (!addressLine1.isEmpty()) {
822	            currentOwner.setAddressLine1(addressLine1);
823	            currentOwner.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
824	            currentOwner.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
825	        } else {
826	            currentOwner.setAddressLine1(null);
827	            currentOwner.setAddressLine2(null);
828	            currentOwner.setAddress(normaliseAddress(ownerFieldsDto.getAddress()));
829	        }
830	        currentOwner.setCity(ownerFieldsDto.getCity());
831	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
832	        currentOwner.setLastName(ownerFieldsDto.getLastName());
833	        currentOwner.setTelephone(telephone);
834	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
835	        this.clinicService.saveOwner(currentOwner);
836	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
837	    }
838	
839	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
